"""Sort semantic version strings by SemVer 2.0.0 precedence."""


def _key(version):
    # Build metadata (after '+') is ignored for precedence.
    core = version.split('+', 1)[0]
    # The pre-release starts at the first hyphen; numeric core parts never contain hyphens.
    if '-' in core:
        base, pre = core.split('-', 1)
    else:
        base, pre = core, None

    major, minor, patch = (int(part) for part in base.split('.'))

    if pre is None:
        # A release sorts above any pre-release of the same core version.
        return (major, minor, patch, 1, ())

    # Numeric identifiers sort below alphanumeric ones; numeric compare as ints,
    # alphanumeric compare in ASCII order (Python str comparison on ASCII).
    ids = tuple(
        (0, int(p), '') if p.isdigit() else (1, 0, p)
        for p in pre.split('.')
    )
    # Tuple comparison makes a shorter list lower when all shared identifiers are equal.
    return (major, minor, patch, 0, ids)


def sort_versions(vs):
    """Return the version strings sorted lowest precedence first.

    Versions that compare equal keep their input order (sorted is stable).
    """
    return sorted(vs, key=_key)
